lab.solution:
def join_quality(learner_ids, completion_ids):
    seen = set()
    duplicates = set()
    for learner_id in learner_ids:
        if learner_id in seen:
            duplicates.add(learner_id)
        seen.add(learner_id)
    unknown = {learner_id for learner_id in completion_ids if learner_id not in seen}
    return {'duplicate_learners': sorted(duplicates), 'unknown_completions': sorted(unknown)}

assert join_quality([1, 2], [1, 1, 3]) == {'duplicate_learners': [], 'unknown_completions': [3]}

